600	+part 'export_job_status_dto.g.dart';
601	+
602	+/// `export.status.get`'s own response `data` (`openapi.yaml:1495-1539`) —
603	+/// decodes every field the contract declares, even [narrativeErrorCode]/
604	+/// [downloadAvailable] which this story never reads (both belong to
605	+/// Story 7.2's download wiring) — kept here so the DTO always mirrors the
606	+/// full contract shape, not just today's consumer.
607	+@JsonSerializable()
608	+class ExportJobStatusDto {
609	+  const ExportJobStatusDto({
610	+    required this.jobId,
611	+    required this.status,
612	+    required this.narrativeStatus,
613	+    required this.entryCount,
614	+    required this.errorCode,
615	+    required this.narrativeErrorCode,
616	+    required this.downloadAvailable,
617	+  });
618	+
619	+  final String jobId;
620	+  final String status;
621	+  final String narrativeStatus;
622	+  final int? entryCount;
623	+  final String? errorCode;
624	+  final String? narrativeErrorCode;
625	+  final bool downloadAvailable;
626	+
627	+  factory ExportJobStatusDto.fromJson(Map<String, dynamic> json) =>
628	+      _$ExportJobStatusDtoFromJson(json);
629	+
630	+  Map<String, dynamic> toJson() => _$ExportJobStatusDtoToJson(this);
631	+
632	+  /// `docs/input/backend/export-screen-states.md`'s own status×
633	+  /// narrativeStatus×downloadAvailable mapping table, implemented once
634	+  /// here — `ExportRepositoryImpl.getStatus`'s own "thin pass-through"
635	+  /// (Code Map) calls straight through to this method, with no mapping
636	+  /// logic of its own.
637	+  ///
638	+  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
639	+  /// new `Failure` subtype") is honored by going through the one shared
640	+  /// [Failure.fromCode] for every `status: 'error'` response and then
641	+  /// branching on the *subtype* it returns, rather than re-testing the
642	+  /// literal `'EXPORT_EMPTY_PERIOD'` string a second time here — this
643	+  /// stays correct even if a future taxonomy edit ever changed which code
644	+  /// means "empty period", with no second place to update.
645	+  ExportJobState toState() {
646	+    switch (status) {
647	+      case 'pending':
648	+        return const ExportJobState.preparing();
649	+      case 'processing':
650	+      case 'data_ready':
651	+        // Design Notes — `data_ready` folds into `generating`'s own
652	+        // visual here, no case of its own (lighting it up is Story
653	+        // 7.2's job).
654	+        return const ExportJobState.generating();
655	+      case 'done':
656	+        return ExportJobState.done(
657	+          narrativeStatus == 'done'
658	+              ? ExportOutcome.narrativeReady
659	+              : ExportOutcome.narrativeUnavailable,
660	+        );
661	+      case 'error':
662	+        final failure = Failure.fromCode(
663	+          errorCode ?? '',
664	+          'Não foi possível gerar a exportação.',
665	+        );
666	+        return failure is ExportEmptyPeriod
667	+            ? const ExportJobState.emptyPeriod()
668	+            : ExportJobState.error(failure);
669	+      default:
670	+        // Forward-compatible: an unrecognized `status` (shouldn't happen —
671	+        // the contract's own enum is closed) never crashes the poll loop
672	+        // (RNF09) — surfaces as a terminal error instead.
673	+        return ExportJobState.error(
674	+          Failure.malformedResponse(
675	+            message: 'Unknown export status: $status',
676	+          ),
677	+        );
678	+    }
679	+  }
680	+}
