694	+/// Thin pass-through over [ExportRemoteDataSource] (Code Map) — no cache
695	+/// (AD-15: export jobs are never persisted locally). [getStatus]'s own
696	+/// DTO→state mapping lives on [ExportJobStatusDto.toState] itself, not
697	+/// here — this class only awaits the data source and relays its result.
698	+class ExportRepositoryImpl implements ExportRepository {
699	+  ExportRepositoryImpl({required this._remoteDataSource});
700	+
701	+  final ExportRemoteDataSource _remoteDataSource;
702	+
703	+  @override
704	+  Future<Either<Failure, String>> createJob({
705	+    required DateTime periodStart,
706	+    required DateTime periodEnd,
707	+  }) => _remoteDataSource.createJob(
708	+    periodStart: periodStart,
709	+    periodEnd: periodEnd,
710	+  );
711	+
712	+  @override
713	+  Future<Either<Failure, ExportJobState>> getStatus(String jobId) async {
714	+    final result = await _remoteDataSource.getStatus(jobId);
715	+    return result.map((dto) => dto.toState());
716	+  }
717	+}
