722	+++ b/lib/features/export/domain/entities/export_job_state.dart
723	@@ -0,0 +1,148 @@
724	+import '../../../../core/failure/failure.dart';
725	+
726	+/// spec-7-1 — the export job's own progress, modeled as its own sealed
727	+/// domain entity (AD-12: never force `status`+`narrativeStatus` into
728	+/// `Resource<T>`), mirroring `BookmarkState`'s own shape: sealed, with
729	+/// `const factory` constructors declared on the base class so call sites
730	+/// read as `ExportJobState.preparing()` rather than naming each subclass
731	+/// directly. Exactly the 5 states `docs/input/backend/export-screen-
732	+/// states.md`'s own status×narrativeStatus×downloadAvailable table
733	+/// collapses into (`data_ready` folds into [ExportJobState.generating],
734	+/// Design Notes — no case of its own here).
735	+///
736	+/// Never persisted (AD-15: ephemeral, polled live) — lives only on
737	+/// `ExportJobCubit.state`.
738	+sealed class ExportJobState {
739	+  const ExportJobState();
740	+
741	+  /// `status: 'pending'` — spinner, "Preparando exportação...". Also this
742	+  /// cubit's own initial state, since `export-summary-create`'s 202
743	+  /// response always answers `status: 'pending'` (`openapi.yaml`), so no
744	+  /// separate "creating..." state is needed before that call resolves.
745	+  const factory ExportJobState.preparing() = ExportJobPreparing;
746	+
747	+  /// `status in {processing, data_ready}` — progress bar, "Gerando resumo
748	+  /// com IA...". `data_ready` renders identically to `processing` here
749	+  /// (Design Notes/Never: lighting up its own download-enabled treatment
750	+  /// is Story 7.2's job).
751	+  const factory ExportJobState.generating() = ExportJobGenerating;
752	+
753	+  /// `status: 'done'` — [outcome] distinguishes "Concluído" (narrative
754	+  /// succeeded, both download buttons shown) from "Narrativa falhou/
755	+  /// pulada" (only the raw-data button, copy scoped to the narrative
756	+  /// failure) without needing two separate sealed variants for what is,
757	+  /// to the job itself, one and the same terminal success.
758	+  const factory ExportJobState.done(ExportOutcome outcome) = ExportJobDone;
759	+
760	+  /// `status: 'error'`, any `errorCode` other than `EXPORT_EMPTY_PERIOD` —
761	+  /// generic error copy, no download, non-retryable/terminal. [failure]
762	+  /// is always built via the one shared `Failure.fromCode` (AD-3) — never
763	+  /// a second, ad hoc mapping of the raw `errorCode` string.
764	+  const factory ExportJobState.error(Failure failure) = ExportJobError;
765	+
766	+  /// `status: 'error'`, `errorCode: 'EXPORT_EMPTY_PERIOD'` — "Nenhum
767	+  /// registro nesse período." + an adjust-period suggestion, no download.
768	+  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
769	+  /// new `Failure` subtype") is honored one layer down, in
770	+  /// `ExportJobStatusDto.toState()`: that mapping step always goes
771	+  /// through `Failure.fromCode` first and only reaches this case by
772	+  /// checking the *subtype* it returns — this variant itself carries no
773	+  /// `Failure` of its own, since by the time the job-level state is
774	+  /// "empty period" there is nothing further for the UI to do with one
775	+  /// (no retry, no message beyond the copy above).
776	+  const factory ExportJobState.emptyPeriod() = ExportJobEmptyPeriod;
777	+}
778	+
779	+/// The default state — outline spinner, tappable only via "Fechar".
780	+class ExportJobPreparing extends ExportJobState {
781	+  const ExportJobPreparing();
782	+
783	+  @override
784	+  bool operator ==(Object other) => other is ExportJobPreparing;
785	+
786	+  @override
787	+  int get hashCode => (ExportJobPreparing).hashCode;
788	+
789	+  @override
790	+  String toString() => 'ExportJobPreparing()';
791	+}
792	+
793	+class ExportJobGenerating extends ExportJobState {
794	+  const ExportJobGenerating();
795	+
796	+  @override
797	+  bool operator ==(Object other) => other is ExportJobGenerating;
798	+
799	+  @override
800	+  int get hashCode => (ExportJobGenerating).hashCode;
801	+
802	+  @override
803	+  String toString() => 'ExportJobGenerating()';
804	+}
805	+
806	+/// [ExportJobDone]'s own two flavors — never a boolean, so a third future
807	+/// outcome (unlikely, but the taxonomy's own `narrativeStatus` enum has
808	+/// exactly `done`/`failed`/`skipped`, the latter two collapsing here into
809	+/// one) never silently reads as the wrong one of only two choices.
810	+enum ExportOutcome {
811	+  /// `narrativeStatus: 'done'` — "Resumo pronto", PDF + raw buttons
812	+  /// (disabled this story; Story 7.2 wires the taps).
813	+  narrativeReady,
814	+
815	+  /// `narrativeStatus in {failed, skipped}` — only the raw-data button
816	+  /// (disabled this story), copy scoped to the narrative failure, not a
817	+  /// job-wide error.
818	+  narrativeUnavailable,
819	+}
820	+
821	+class ExportJobDone extends ExportJobState {
822	+  const ExportJobDone(this.outcome);
823	+
824	+  final ExportOutcome outcome;
825	+
826	+  @override
827	+  bool operator ==(Object other) =>
828	+      identical(this, other) || (other is ExportJobDone && other.outcome == outcome);
829	+
830	+  @override
831	+  int get hashCode => outcome.hashCode;
832	+
833	+  @override
834	+  String toString() => 'ExportJobDone(outcome: $outcome)';
835	+}
836	+
837	+/// The job itself failed — red warning, terminal (I/O matrix: "Non-
838	+/// retryable, terminal"). [failure] is kept for parity with
839	+/// `BookmarkError`'s own shape, even though the sheet only ever needs
840	+/// generic error copy, never [failure].message, for this variant (the
841	+/// taxonomy's own 13 codes carry no export-specific text).
842	+class ExportJobError extends ExportJobState {
843	+  const ExportJobError(this.failure);
844	+
845	+  final Failure failure;
846	+
847	+  @override
848	+  bool operator ==(Object other) =>
849	+      identical(this, other) || (other is ExportJobError && other.failure == failure);
850	+
851	+  @override
852	+  int get hashCode => failure.hashCode;
853	+
854	+  @override
855	+  String toString() => 'ExportJobError(failure: $failure)';
856	+}
857	+
858	+/// "Período vazio" — see [ExportJobState.emptyPeriod]'s own doc for why
859	+/// this variant carries no [Failure] of its own.
860	+class ExportJobEmptyPeriod extends ExportJobState {
861	+  const ExportJobEmptyPeriod();
862	+
863	+  @override
864	+  bool operator ==(Object other) => other is ExportJobEmptyPeriod;
865	+
866	+  @override
867	+  int get hashCode => (ExportJobEmptyPeriod).hashCode;
868	+
869	+  @override
870	+  String toString() => 'ExportJobEmptyPeriod()';
871	+}
