876	+++ b/lib/features/export/domain/repositories/export_repository.dart
877	@@ -0,0 +1,31 @@
878	+import 'package:fpdart/fpdart.dart';
879	+
880	+import '../../../../core/failure/failure.dart';
881	+import '../entities/export_job_state.dart';
882	+
883	+/// The export feature's one port (RNF06) — `features/export/presentation`
884	+/// depends on this abstract class only, never `export/data` directly.
885	+/// Every method returns `Either<Failure, T>` (RNF09).
886	+abstract class ExportRepository {
887	+  /// Calls `export-summary-create` (`ApiClient.post`) — RF05's own job
888	+  /// kickoff for the period [periodStart]..[periodEnd]. Returns the
889	+  /// created job's `jobId` on success. `RetryInterceptor.
890	+  /// neverRetriedFunctions` already excludes this call from any
891	+  /// transparent retry (non-idempotent POST, no idempotency key) — every
892	+  /// [Failure] here, including a theoretical synchronous rejection,
893	+  /// propagates as `Left`, unmapped.
894	+  Future<Either<Failure, String>> createJob({
895	+    required DateTime periodStart,
896	+    required DateTime periodEnd,
897	+  });
898	+
899	+  /// Calls `export-status-get` (`ApiClient.get`, [jobId] appended as the
900	+  /// one trailing path segment) and maps the response straight into
901	+  /// [ExportJobState] — a thin pass-through, no cache (AD-15: ephemeral,
902	+  /// polled live). `Left` here is a transport-level failure only
903	+  /// (offline/timeout/malformed) — a backend-reported job failure
904	+  /// (including the empty-period case) already arrives as a
905	+  /// `Right(ExportJobState.error(...))`/`Right(ExportJobState.
906	+  /// emptyPeriod())`, never as a `Left`.
907	+  Future<Either<Failure, ExportJobState>> getStatus(String jobId);
908	+}
